// I Love TV! Suite — Art Deco input-bar workspace
export function setup(ctx) {
  const s={chatId:null,tab:'broadcast',ledger:{affinity:0,dynamic:'',continuity:{},settings:{expandChoices:true,trackerInterval:1},lastActions:[]},suite:{enabled:true,selectedVersion:'3.5',rpgMode:false,versions:[],blocks:[],variables:[],archives:[]},connections:[],choices:[],block:null,search:'',choiceBusy:false,rewriteBusy:false,requestId:null,clipboard:null,dragId:null};
  let modal=null;const cleanups=[];
  const esc=(v='')=>String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
  const clean=(v='')=>String(v).replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu,'').replace(/^[\s━─⋆⟢✦✧★☆·•]+/u,'').trim();
  const send=(type,p={})=>ctx.sendToBackend({type,chatId:s.chatId||undefined,...p});
  const requestState=()=>send('control_room:get_state');
  const icons={
    broadcast:'<svg viewBox="0 0 24 24"><rect x="3" y="6" width="18" height="14" rx="1"/><path d="m8 2 4 4 4-4M7 11h7M7 15h5M18 11v5"/></svg>',
    preset:'<svg viewBox="0 0 24 24"><path d="M4 5h16M4 12h16M4 19h16"/><circle cx="9" cy="5" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="7" cy="19" r="2"/></svg>',
    blocks:'<svg viewBox="0 0 24 24"><path d="m12 3 8 4-8 4-8-4 8-4Z"/><path d="m4 12 8 4 8-4M4 17l8 4 8-4"/></svg>',
    director:'<svg viewBox="0 0 24 24"><path d="M4 4h16v16H4zM4 9h16M9 4l-3 5M15 4l-3 5M21 4l-3 5"/><path d="m10 13 5 2.5-5 2.5Z"/></svg>',
    memory:'<svg viewBox="0 0 24 24"><path d="M9 4a4 4 0 0 0-4 4v1a3 3 0 0 0 0 6v1a4 4 0 0 0 4 4M15 4a4 4 0 0 1 4 4v1a3 3 0 0 1 0 6v1a4 4 0 0 1-4 4M9 8h6M9 12h6M9 16h6"/></svg>',
    tools:'<svg viewBox="0 0 24 24"><path d="M14 6a4 4 0 0 0 4 4l-8 8-4-4 8-8Z"/><path d="m5 13-2 2 6 6 2-2M15 3l6 6"/></svg>',
    category:'<svg viewBox="0 0 24 24"><path d="M3 7h7l2 2h9v10H3zM3 7V5h7l2 2"/></svg>',marker:'<svg viewBox="0 0 24 24"><path d="M6 3v18M6 5h12l-3 4 3 4H6"/></svg>',block:'<svg viewBox="0 0 24 24"><rect x="4" y="3" width="16" height="18" rx="1"/><path d="M8 8h8M8 12h8M8 16h5"/></svg>',archive:'<svg viewBox="0 0 24 24"><path d="M4 7h16v13H4zM3 3h18v4H3zM9 11h6"/></svg>',drag:'<svg viewBox="0 0 24 24"><circle cx="9" cy="6" r="1"/><circle cx="15" cy="6" r="1"/><circle cx="9" cy="12" r="1"/><circle cx="15" cy="12" r="1"/><circle cx="9" cy="18" r="1"/><circle cx="15" cy="18" r="1"/></svg>'
  };
  const icon=n=>`<span class="tv-icon">${icons[n]||icons.block}</span>`;
  function toast(message){let e=document.getElementById('ilovetv-suite-toast');if(!e){e=document.createElement('div');e.id='ilovetv-suite-toast';e.className='tv-toast';document.body.appendChild(e)}e.textContent=message;e.style.opacity='1';setTimeout(()=>e.style.opacity='0',2800)}
  function composer(){return document.querySelector('textarea[name="chat-message"]')||document.querySelector('[data-component="InputArea"] textarea')||document.querySelector('textarea[placeholder*="message" i]')}
  function writeComposer(text){const t=composer();if(!t){toast('Could not locate the Lumiverse message composer.');return false}const set=Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype,'value')?.set;t.focus();if(set)set.call(t,text);else t.value=text;t.dispatchEvent(new InputEvent('input',{bubbles:true,composed:true,inputType:'insertText',data:text}));t.dispatchEvent(new Event('change',{bubbles:true,composed:true}));t.selectionStart=t.selectionEnd=t.value.length;toast('Editable draft placed in the composer.');return true}
  function parseChoices(content){const text=String(content||'');const body=text.match(/<cyoa_choices\b[^>]*>([\s\S]*?)<\/cyoa_choices>/i)?.[1]||text;return body.split(/\r?\n/).map(x=>x.match(/^\s*\[(\d+)\]\s*(.+?)\s*$/)).filter(Boolean).map(m=>({number:Number(m[1]),text:m[2].trim()})).slice(0,8)}
  function captureChoices(content){const c=parseChoices(content);if(!c.length)return false;s.choices=c;toast(`${c.length} Director's Cut choices are ready.`);render();return true}
  function choose(index){const c=s.choices[index];if(!c||s.choiceBusy)return;if(s.ledger.settings?.expandChoices===false){if(writeComposer(String(c.number)))s.choices=[];render();return}s.choiceBusy=true;s.requestId=crypto.randomUUID();toast('Writing the selected option as the user character.');send('control_room:expand_choice',{requestId:s.requestId,option:`[${c.number}] ${c.text}`});render()}
  const tabs=[['broadcast','Broadcast'],['preset','Preset'],['blocks','Blocks'],['director','Director'],['memory','Memory'],['tools','Tools']];
  const css=`<style>
  .tv{--gold:#c69b4b;--gold2:#e1c27c;--ink:#080d0a;--green:#0d1a13;--wine:#30090e;--cream:#eadbb8;color:var(--cream);font:13px/1.5 Georgia,'Times New Roman',serif}.tv *{box-sizing:border-box}.tv svg{width:100%;height:100%;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.tv-head{position:relative;display:flex;align-items:center;gap:14px;padding:9px 12px 16px;border-bottom:1px solid var(--gold);background:linear-gradient(100deg,#23080caa,#07100baa)}.tv-head:after{content:'';position:absolute;left:0;right:0;bottom:3px;border-bottom:1px solid #c69b4b66}.tv-logo{width:46px;height:46px;padding:7px;color:var(--gold2);border:1px solid var(--gold);background:radial-gradient(circle,#193021,#070b08);clip-path:polygon(50% 0,91% 18%,100% 50%,91% 82%,50% 100%,9% 82%,0 50%,9% 18%)}.tv-title{font-size:18px;letter-spacing:.19em;color:var(--gold2)}.tv-kicker,.tv-label{font:600 10px/1.3 system-ui,sans-serif;letter-spacing:.17em;text-transform:uppercase;color:var(--gold)}.tv-live{margin-left:auto;font:700 10px system-ui;letter-spacing:.14em;color:#e9c178}.tv-dot{display:inline-block;width:7px;height:7px;margin-right:7px;border-radius:50%;background:#d93b32;box-shadow:0 0 10px #e33}.tv-tabs{display:grid;grid-template-columns:repeat(6,1fr);gap:3px;padding:10px 0}.tv-tab{display:flex;align-items:center;justify-content:center;gap:6px;border:1px solid #c69b4b55;background:#0b120e;color:#baa779;padding:8px 6px;cursor:pointer;font:600 10px system-ui;letter-spacing:.08em;text-transform:uppercase}.tv-tab.on{border-color:var(--gold2);background:linear-gradient(#3b0b12,#22070b);color:var(--gold2);box-shadow:inset 0 0 0 2px #090d0a}.tv-icon{display:inline-grid;width:18px;height:18px;flex:0 0 18px;color:var(--gold)}.tv-panel{display:flex;flex-direction:column;gap:10px;max-height:620px;overflow:auto;padding:4px 3px 10px;scrollbar-color:#9b7133 #0b100d}.tv-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.tv-card,.tv-row{position:relative;border:1px solid #9f7538;background:linear-gradient(140deg,#0e1b13,#0a0e0b 72%,#26080c);padding:12px;box-shadow:inset 0 0 0 2px #040805}.tv-card:before,.tv-row:before{content:'';position:absolute;width:10px;height:10px;left:3px;top:3px;border-left:1px solid #e0bd70;border-top:1px solid #e0bd70}.tv-row{display:flex;flex-direction:column;gap:7px}.tv-muted{font:11px/1.5 system-ui,sans-serif;color:#aa9f89}.tv-input{width:100%;padding:9px;border:1px solid #80612f;background:#070b08;color:#eee2c8;font:12px/1.45 system-ui,sans-serif}.tv-input:focus{outline:1px solid var(--gold2);box-shadow:0 0 0 3px #c69b4b18}.tv-btn{display:inline-flex;align-items:center;gap:5px;border:1px solid var(--gold);background:linear-gradient(#371016,#1b090b);color:#e5c982;padding:7px 11px;font:700 10px system-ui;letter-spacing:.08em;text-transform:uppercase;cursor:pointer}.tv-btn.secondary{background:#0c1610}.tv-btn.danger{border-color:#96454b;color:#e6a1a1}.tv-actions{display:flex;gap:6px;flex-wrap:wrap}.tv-list{margin:5px 0 0;padding-left:18px}.tv-blocks{display:grid;grid-template-columns:minmax(250px,.85fr) minmax(330px,1.35fr);gap:10px}.tv-block-list{max-height:480px;overflow:auto;padding:0}.tv-block{display:flex;width:100%;gap:7px;align-items:center;text-align:left;border:0;border-bottom:1px solid #80612f55;background:#070b08;color:#d9cba9;padding:7px;cursor:pointer}.tv-block[data-kind="category"]{margin-top:5px;background:#2b0a0e;color:#e4c579;text-transform:uppercase;letter-spacing:.08em}.tv-block[data-kind="marker"]{background:#101b14;color:#c8b98f}.tv-block.on{box-shadow:inset 3px 0 var(--gold2);background:#3a1015}.tv-block.drag-over{outline:1px solid var(--gold2)}.tv-drag{width:15px;height:19px;color:#806b45;cursor:grab}.tv-block-name{flex:1;font:11px/1.25 system-ui,sans-serif}.tv-chip{font:700 8px system-ui;border:1px solid #876834;padding:2px 4px;text-transform:uppercase}.tv-editor{min-height:260px;font:11px/1.45 ui-monospace,monospace;resize:vertical}.tv-meter{font:400 33px Georgia;color:var(--gold2)}.tv-log{font:10px/1.45 ui-monospace;padding:5px 0;border-bottom:1px dashed #80612f55}.tv-choice{width:100%;text-align:left;border:1px solid #9f7538;border-left:4px double var(--gold2);background:#0b160f;color:#eadbb8;padding:11px;cursor:pointer}.tv-var-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.tv-var{display:flex;flex-direction:column;gap:5px;border-top:1px solid #80612f55;padding-top:8px}.tv-var-group{display:flex;flex-direction:column;gap:8px}.tv-switch{display:flex;align-items:center;gap:8px}.tv-archive{display:flex;align-items:center;gap:7px;padding:7px;border-bottom:1px solid #80612f44}.tv-toast{position:fixed;bottom:84px;left:50%;transform:translateX(-50%);z-index:99999;padding:9px 17px;border:1px solid #c69b4b;background:#18090b;color:#eadbb8;font:700 11px system-ui;letter-spacing:.05em;box-shadow:0 8px 28px #000c;pointer-events:none;transition:opacity .2s}.tv-fields{display:grid;grid-template-columns:2fr 1fr 1fr;gap:7px}.tv-ornament{height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent);margin:3px 0}.tv-busy{display:flex;align-items:center;gap:10px}.tv-spinner{width:18px;height:18px;border:1px solid #5b482a;border-top-color:var(--gold2);border-radius:50%;animation:tvspin .7s linear infinite}@keyframes tvspin{to{transform:rotate(360deg)}}@media(max-width:760px){.tv-grid,.tv-blocks,.tv-var-grid{grid-template-columns:1fr}.tv-tabs{grid-template-columns:repeat(3,1fr)}.tv-fields{grid-template-columns:1fr}}
  </style>`;
  const list=(a,f)=>Array.isArray(a)&&a.length?`<ul class="tv-list">${a.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:`<div class="tv-muted">${f}</div>`;
  function broadcast(){const t=s.ledger.lastTurn||{};return `<div class="tv-grid"><div class="tv-card"><div class="tv-label">Affinity</div><div class="tv-meter">${Number(s.ledger.affinity)||0}%</div><div class="tv-muted">Last delta ${Number(t.delta||0)>=0?'+':''}${Number(t.delta||0)}%</div></div><div class="tv-card"><div class="tv-label">Locked checks</div><div class="tv-meter" style="font-size:23px">D4 ${t.pathRoll||'—'} · D20 ${t.d20Roll||'—'}</div><div class="tv-muted">${t.backgroundSucceeded?'Director pass successful':'Awaiting a successful pass'}</div></div></div><div class="tv-card"><div class="tv-label">Dynamic subtext</div>${esc(s.ledger.dynamic||'Awaiting analysis.')}</div><div class="tv-card"><div class="tv-label">Immediate episode target</div>${esc(s.ledger.continuity?.episodeTarget||'Awaiting analysis.')}</div><div class="tv-card"><div class="tv-label">Season arc</div>${esc(s.ledger.continuity?.seasonArc||'Awaiting analysis.')}</div>`}
  function variableControl(g,v){const attrs=`data-variable data-block-id="${esc(g.blockId)}" data-var-name="${esc(v.name)}"`;if(v.type==='select')return `<label class="tv-var"><span>${esc(clean(v.label||v.name))}</span><select class="tv-input" ${attrs}>${(v.options||[]).map(o=>`<option value="${esc(o.id)}" ${String(o.id)===String(v.value)?'selected':''}>${esc(clean(o.label||o.id))}</option>`).join('')}</select><span class="tv-muted">${esc(v.description||'')}</span></label>`;if(v.type==='switch'||typeof v.value==='boolean'||[0,1].includes(v.defaultValue))return `<label class="tv-var tv-switch"><input type="checkbox" ${attrs} ${v.value===true||Number(v.value)===1?'checked':''}><span><b>${esc(clean(v.label||v.name))}</b><br><span class="tv-muted">${esc(v.description||'')}</span></span></label>`;return `<label class="tv-var"><span>${esc(clean(v.label||v.name))}</span><input class="tv-input" type="${v.type==='number'||typeof v.defaultValue==='number'?'number':'text'}" value="${esc(v.value??'')}" ${attrs}><span class="tv-muted">${esc(v.description||'')}</span></label>`}
  function preset(){const opts=(s.suite.versions||[]).map(v=>`<option value="${esc(v.id)}" ${v.id===s.suite.selectedVersion?'selected':''}>${esc(clean(v.label))} · ${v.blockCount} blocks</option>`).join('');const groups=(s.suite.variables||[]).map(g=>`<div class="tv-row tv-var-group"><div class="tv-label">${esc(clean(g.blockName))}</div><div class="tv-var-grid">${(g.variables||[]).map(v=>variableControl(g,v)).join('')}</div></div>`).join('');return `<div class="tv-row"><label class="tv-label">Bundled preset version</label><select id="tv-version" class="tv-input">${opts}</select><div class="tv-muted">Assembled by the extension. The external preset is not required.</div></div><label class="tv-card tv-switch"><input id="tv-enabled" type="checkbox" ${s.suite.enabled!==false?'checked':''}><span>Use the bundled suite prompt for generations</span></label><div class="tv-ornament"></div><div class="tv-label">Lumiverse prompt variables</div>${groups||'<div class="tv-card tv-muted">No configurable variables are exposed by this version.</div>'}`}
  function blockEditor(){if(!s.block)return '<div class="tv-card tv-muted">Select a category, marker, or prompt block to inspect it.</div>';const b=s.block;return `<div class="tv-row"><div class="tv-label">Block workshop</div><div class="tv-fields"><input id="tv-name" class="tv-input" value="${esc(clean(b.name))}" placeholder="Name"><select id="tv-role" class="tv-input"><option ${b.role==='system'?'selected':''}>system</option><option ${b.role==='user'?'selected':''}>user</option><option ${b.role==='assistant'?'selected':''}>assistant</option></select><select id="tv-position" class="tv-input"><option ${b.position==='pre_history'?'selected':''}>pre_history</option><option ${b.position==='post_history'?'selected':''}>post_history</option></select></div><div class="tv-fields"><input id="tv-marker" class="tv-input" value="${esc(b.marker||'')}" placeholder="Marker"><input id="tv-depth" class="tv-input" type="number" min="0" value="${Number(b.depth||0)}"><label class="tv-switch"><input id="tv-block-enabled" type="checkbox" ${b.enabled!==false?'checked':''}> Enabled</label></div><textarea id="tv-content" class="tv-input tv-editor">${esc(b.content||'')}</textarea><textarea id="tv-directions" class="tv-input" rows="3" placeholder="Direct the selected model to rewrite or build this prompt."></textarea><div class="tv-actions"><button id="tv-save-block" class="tv-btn">Save</button><button id="tv-rewrite" class="tv-btn secondary">${s.rewriteBusy?'Writing':'AI draft'}</button><button id="tv-duplicate" class="tv-btn secondary">Duplicate</button><button id="tv-copy" class="tv-btn secondary">Copy</button><button id="tv-archive" class="tv-btn secondary">Archive copy</button><button id="tv-reset" class="tv-btn danger">Reset bundled</button></div><div class="tv-muted">AI output stays a draft until Save is selected. Archive copy preserves a snapshot without removing the live block.</div></div>`}
  function blocks(){const q=s.search.toLowerCase();const bs=(s.suite.blocks||[]).filter(b=>!q||clean(b.name).toLowerCase().includes(q));const items=bs.map(b=>`<button draggable="true" class="tv-block ${s.block?.id===b.id?'on':''}" data-block="${esc(b.id)}" data-kind="${esc(b.kind||'block')}"><span class="tv-drag">${icons.drag}</span>${icon(b.kind||'block')}<input type="checkbox" tabindex="-1" ${b.enabled?'checked':''}><span class="tv-block-name">${esc(clean(b.name))}</span>${b.edited?'<span class="tv-chip">edited</span>':''}${b.custom?'<span class="tv-chip">custom</span>':''}</button>`).join('');const archives=(s.suite.archives||[]).map(a=>`<div class="tv-archive">${icon('archive')}<span class="tv-block-name">${esc(clean(a.name))}</span><button class="tv-btn secondary" data-restore="${esc(a.archiveId)}">Restore</button></div>`).join('');return `<div class="tv-actions"><button class="tv-btn" data-add="block">Add block</button><button class="tv-btn" data-add="category">Add category</button><button class="tv-btn" data-add="marker">Add marker</button><button id="tv-paste" class="tv-btn secondary" ${s.clipboard?'':'disabled'}>Paste copy</button></div><div class="tv-blocks"><div><input id="tv-search" class="tv-input" placeholder="Search prompt structure" value="${esc(s.search)}"><div class="tv-card tv-block-list">${items}</div><details class="tv-card"><summary>${icon('archive')} Archive folder (${(s.suite.archives||[]).length})</summary>${archives||'<div class="tv-muted">No archived snapshots.</div>'}</details></div>${blockEditor()}</div>`}
  function director(){const opts=['<option value="">Active/default connection</option>',...(s.connections||[]).map(c=>`<option value="${esc(c.id)}" ${c.id===s.ledger.selectedConnection?'selected':''}>${esc(c.name)}</option>`)].join('');const logs=(s.ledger.lastActions||[]).slice(-14).reverse().map(x=>`<div class="tv-log">${esc(x)}</div>`).join('');return `<div class="tv-row"><label class="tv-label">Background connection</label><select id="tv-connection" class="tv-input">${opts}</select></div><div class="tv-row"><label class="tv-label">Author's note</label><textarea id="tv-note" class="tv-input" rows="3">${esc(s.ledger.authorNote||'')}</textarea></div><div class="tv-row"><label class="tv-label">Tracker cadence</label><input id="tv-interval" class="tv-input" type="number" min="1" max="10" value="${Number(s.ledger.settings?.trackerInterval||1)}"></div><button id="tv-save-director" class="tv-btn">Save director settings</button><div class="tv-card"><div class="tv-label">Director telemetry</div>${logs||'<div class="tv-muted">No passes yet.</div>'}</div>`}
  function memory(){const c=s.ledger.continuity||{};return `<div class="tv-card"><div class="tv-label">Running story summary</div>${esc(c.runningSummary||'The suite summarizer will update this on the next tracker pass.')}</div><div class="tv-card"><div class="tv-label">Core memories</div>${list(c.coreMemories,'None captured yet.')}</div><div class="tv-card"><div class="tv-label">B-plots and flags</div>${list(c.bPlots,'None captured yet.')}</div><div class="tv-card"><div class="tv-label">Possible future branches</div>${list(c.futureBranches,'None predicted yet.')}</div>`}
  function tools(){const choices=s.choiceBusy?'<div class="tv-card tv-busy"><span class="tv-spinner"></span>Writing the user-character draft.</div>':s.choices.length?s.choices.map((c,i)=>`<button class="tv-choice" data-choice="${i}">[${c.number}] ${esc(c.text)}</button>`).join(''):'<div class="tv-card tv-muted">CYOA choices will appear here after a response.</div>';return `<label class="tv-card tv-switch"><input id="tv-expand" type="checkbox" ${s.ledger.settings?.expandChoices!==false?'checked':''}> AI writes selected CYOA choices as the user character</label><label class="tv-card tv-switch"><input id="tv-rpg" type="checkbox" ${s.suite.rpgMode?'checked':''}> RPG mode: locked checks, inventory, conditions, and objectives</label>${choices}`}
  function render(){if(!modal)return;const panel=s.tab==='broadcast'?broadcast():s.tab==='preset'?preset():s.tab==='blocks'?blocks():s.tab==='director'?director():s.tab==='memory'?memory():tools();modal.root.innerHTML=`${css}<div class="tv"><div class="tv-head"><div class="tv-logo">${icons.broadcast}</div><div><div class="tv-kicker">The Broadcast Control System</div><div class="tv-title">I LOVE TV! SUITE</div></div><div class="tv-live"><span class="tv-dot"></span>${s.suite.enabled===false?'STANDBY':'ON AIR'}</div></div><nav class="tv-tabs">${tabs.map(([id,label])=>`<button class="tv-tab ${id===s.tab?'on':''}" data-tab="${id}">${icon(id)}${label}</button>`).join('')}</nav><section class="tv-panel">${panel}</section></div>`;bind()}
  function saveBlock(){if(!s.block)return;send('suite:save_block',{blockId:s.block.id,name:modal.root.querySelector('#tv-name').value.trim(),role:modal.root.querySelector('#tv-role').value,position:modal.root.querySelector('#tv-position').value,marker:modal.root.querySelector('#tv-marker').value.trim()||null,depth:Number(modal.root.querySelector('#tv-depth').value||0),enabled:modal.root.querySelector('#tv-block-enabled').checked,content:modal.root.querySelector('#tv-content').value})}
  function bind(){modal.root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{s.tab=b.dataset.tab;render()});modal.root.querySelector('#tv-version')?.addEventListener('change',e=>send('suite:select_version',{versionId:e.target.value}));modal.root.querySelector('#tv-enabled')?.addEventListener('change',e=>send('suite:save_settings',{enabled:e.target.checked,rpgMode:s.suite.rpgMode}));modal.root.querySelector('#tv-rpg')?.addEventListener('change',e=>send('suite:save_settings',{enabled:s.suite.enabled,rpgMode:e.target.checked}));modal.root.querySelector('#tv-expand')?.addEventListener('change',e=>send('control_room:save_ledger',{ledger:{settings:{...s.ledger.settings,expandChoices:e.target.checked}}}));modal.root.querySelectorAll('[data-variable]').forEach(el=>el.addEventListener('change',()=>send('suite:save_variable',{blockId:el.dataset.blockId,name:el.dataset.varName,value:el.type==='checkbox'?(el.checked?1:0):el.type==='number'?Number(el.value):el.value})));modal.root.querySelector('#tv-search')?.addEventListener('input',e=>{s.search=e.target.value;render()});modal.root.querySelectorAll('[data-block]').forEach(b=>{b.onclick=e=>{if(e.target instanceof HTMLInputElement)send('suite:save_block',{blockId:b.dataset.block,enabled:e.target.checked});else if(!e.target.closest('.tv-drag'))send('suite:get_block',{blockId:b.dataset.block})};b.ondragstart=e=>{s.dragId=b.dataset.block;e.dataTransfer.effectAllowed='move'};b.ondragover=e=>{e.preventDefault();b.classList.add('drag-over')};b.ondragleave=()=>b.classList.remove('drag-over');b.ondrop=e=>{e.preventDefault();b.classList.remove('drag-over');const target=b.dataset.block;if(!s.dragId||s.dragId===target)return;const order=(s.suite.blocks||[]).map(x=>x.id).filter(id=>id!==s.dragId);order.splice(order.indexOf(target),0,s.dragId);send('suite:reorder_blocks',{order});s.dragId=null}});modal.root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>send('suite:create_block',{kind:b.dataset.add,afterId:s.block?.id}));modal.root.querySelector('#tv-save-block')?.addEventListener('click',saveBlock);modal.root.querySelector('#tv-reset')?.addEventListener('click',()=>send('suite:reset_block',{blockId:s.block.id}));modal.root.querySelector('#tv-duplicate')?.addEventListener('click',()=>send('suite:duplicate_block',{blockId:s.block.id}));modal.root.querySelector('#tv-copy')?.addEventListener('click',()=>{s.clipboard={...s.block,name:`${clean(s.block.name)} — Copy`};toast('Block copied inside the suite.');render()});modal.root.querySelector('#tv-paste')?.addEventListener('click',()=>s.clipboard&&send('suite:create_block',{kind:s.clipboard.marker==='category'?'category':s.clipboard.marker?'marker':'block',afterId:s.block?.id,...s.clipboard,id:undefined}));modal.root.querySelector('#tv-archive')?.addEventListener('click',()=>send('suite:archive_block',{blockId:s.block.id}));modal.root.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>send('suite:restore_archive',{archiveId:b.dataset.restore}));modal.root.querySelector('#tv-rewrite')?.addEventListener('click',()=>{s.rewriteBusy=true;s.requestId=crypto.randomUUID();send('suite:rewrite_block',{requestId:s.requestId,blockId:s.block.id,content:modal.root.querySelector('#tv-content').value,directions:modal.root.querySelector('#tv-directions').value});render()});modal.root.querySelector('#tv-save-director')?.addEventListener('click',()=>send('control_room:save_ledger',{ledger:{selectedConnection:modal.root.querySelector('#tv-connection').value,authorNote:modal.root.querySelector('#tv-note').value.trim(),settings:{...s.ledger.settings,trackerInterval:Math.max(1,Math.min(10,Number(modal.root.querySelector('#tv-interval').value||1)))}}}));modal.root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.choice)))}
  function open(){requestState();if(!modal){modal=ctx.ui.showModal({title:'I Love TV! Suite',width:940,maxHeight:860});modal.onDismiss(()=>modal=null)}render()}
  cleanups.push(ctx.onBackendMessage(p=>{if(!p)return;if(p.type==='control_room:state_data'||p.type==='control_room:save_success'){if(p.chatId)s.chatId=p.chatId;if(p.ledger)s.ledger=p.ledger;if(p.connections)s.connections=p.connections;if(p.suite)s.suite={...s.suite,...p.suite};render()}if(p.type==='suite:config_saved'){s.suite={...s.suite,...p.suite};toast('Suite configuration saved.');render()}if(p.type==='suite:block_data'){s.block=p.block;s.tab='blocks';render()}if(p.type==='suite:block_saved'){s.block=p.block;if(p.suite)s.suite={...s.suite,...p.suite};toast('Prompt structure saved.');render()}if(p.type==='suite:rewrite_ready'&&p.requestId===s.requestId){s.rewriteBusy=false;s.block={...s.block,content:p.content};toast('AI draft ready for review.');render()}if(p.type==='suite:rewrite_error'&&p.requestId===s.requestId){s.rewriteBusy=false;toast(`Prompt rewrite failed: ${p.error}`);render()}if(p.type==='control_room:choice_expanded'&&p.requestId===s.requestId){s.choiceBusy=false;s.requestId=null;if(writeComposer(p.text))s.choices=[];render()}if(p.type==='control_room:choice_error'&&p.requestId===s.requestId){s.choiceBusy=false;s.requestId=null;toast(`Choice writer failed: ${p.error}`);render()}}));if(ctx.messages?.registerTagInterceptor)cleanups.push(ctx.messages.registerTagInterceptor({tagName:'cyoa_choices'},p=>{if(!p.isStreaming)captureChoices(p.content)}));if(ctx.events?.on){cleanups.push(ctx.events.on('GENERATION_ENDED',p=>captureChoices(p?.content)));cleanups.push(ctx.events.on('CHAT_SWITCHED',p=>{s.chatId=p?.chatId||null;s.choices=[];s.block=null;requestState();render()}))}if(ctx.ui?.registerInputBarAction){const a=ctx.ui.registerInputBarAction({id:'i-love-tv-suite',label:'I Love TV! Suite',iconSvg:icons.broadcast});cleanups.push(a.onClick(open),()=>a.destroy())}requestState();return()=>{cleanups.reverse().forEach(f=>{try{f?.()}catch{}});modal?.dismiss?.();document.getElementById('ilovetv-suite-toast')?.remove()}
}

